/*Table structure for table `biz_favorite` */

DROP TABLE IF EXISTS `biz_favorite`;

CREATE TABLE `biz_favorite` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '涓婚敭ID',
  `user_id` bigint(20) NOT NULL COMMENT '鐢ㄦ埛ID',
  `target_type` tinyint(4) NOT NULL COMMENT '鐩?爣绫诲瀷:1閰掑簵 2鏅?偣 3椁愬巺',
  `target_id` bigint(20) NOT NULL COMMENT '鐩?爣ID',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_target` (`user_id`,`target_type`,`target_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COMMENT='鏀惰棌琛';

