/*Table structure for table `biz_hotel_room` */

DROP TABLE IF EXISTS `biz_hotel_room`;

CREATE TABLE `biz_hotel_room` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '涓婚敭ID',
  `hotel_id` bigint(20) NOT NULL COMMENT '鎵?睘閰掑簵ID',
  `name` varchar(100) NOT NULL COMMENT '鎴垮瀷鍚嶇О',
  `price` decimal(10,2) NOT NULL COMMENT '鍗曚环(鍏?鏅?',
  `original_price` decimal(10,2) DEFAULT NULL COMMENT '鍘熶环(鍒掔嚎浠?',
  `total_count` int(11) NOT NULL DEFAULT '0' COMMENT '鎬绘埧闂存暟',
  `remaining_count` int(11) NOT NULL DEFAULT '0' COMMENT '鍓╀綑鎴块棿鏁',
  `bed_type` varchar(50) DEFAULT NULL COMMENT '搴婂瀷',
  `area` varchar(50) DEFAULT NULL COMMENT '闈㈢Н',
  `max_guests` int(11) NOT NULL DEFAULT '2' COMMENT '鏈??鍏ヤ綇浜烘暟',
  `breakfast` tinyint(4) NOT NULL DEFAULT '0' COMMENT '鏄?惁鍚?棭:0鍚?1鏄',
  `image` varchar(255) DEFAULT NULL COMMENT '鎴垮瀷鍥剧墖URL',
  `description` varchar(500) DEFAULT NULL COMMENT '鎴垮瀷鎻忚堪',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '鐘舵?:0涓嬫灦 1涓婃灦',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  PRIMARY KEY (`id`),
  KEY `idx_hotel` (`hotel_id`)
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8mb4 COMMENT='閰掑簵鎴垮瀷琛';

