/*Table structure for table `biz_merchant` */

DROP TABLE IF EXISTS `biz_merchant`;

CREATE TABLE `biz_merchant` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '涓婚敭ID',
  `username` varchar(50) NOT NULL COMMENT '鐧诲綍鍚',
  `password` varchar(100) NOT NULL COMMENT '瀵嗙爜(BCrypt鍔犲瘑)',
  `name` varchar(100) DEFAULT NULL COMMENT '鍟嗗?鍚嶇О',
  `type` tinyint(4) NOT NULL DEFAULT '1' COMMENT '鍟嗗?绫诲瀷:1閰掑簵 2椁愬巺 3缁煎悎',
  `contact_name` varchar(50) DEFAULT NULL COMMENT '鑱旂郴浜',
  `contact_phone` varchar(20) DEFAULT NULL COMMENT '鑱旂郴鐢佃瘽',
  `email` varchar(100) DEFAULT NULL COMMENT '閭??',
  `address` varchar(255) DEFAULT NULL COMMENT '缁忚惀鍦板潃',
  `description` text COMMENT '鍟嗗?绠?粙',
  `logo` varchar(255) DEFAULT NULL COMMENT 'Logo URL',
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '瀹℃牳鐘舵?:0寰呭?鏍?1閫氳繃 2椹冲洖 3绂佺敤',
  `audit_reason` varchar(255) DEFAULT NULL COMMENT '瀹℃牳椹冲洖鍘熷洜',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username` (`username`)
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COMMENT='鍟嗗?琛';

/*Data for the table `biz_merchant` */

