/*Table structure for table `biz_notice` */

DROP TABLE IF EXISTS `biz_notice`;

CREATE TABLE `biz_notice` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '涓婚敭ID',
  `title` varchar(100) NOT NULL COMMENT '鏍囬?',
  `content` text COMMENT '鍐呭?',
  `publisher_id` bigint(20) DEFAULT NULL COMMENT '鍙戝竷绠＄悊鍛業D',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '鐘舵?:0涓嬫灦 1鍙戝竷',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '鍙戝竷鏃堕棿',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='鍏?憡琛';

/*Data for the table `biz_notice` */

insert  into `biz_notice`(`id`,`title`,`content`,`publisher_id`,`status`,`create_time`) values (1,'平台上线公告','旅游服务平台正式上线，欢迎广大用户与商家入驻！',1,1,'2026-10-07 13:59:22'),(2,'国庆假期预订提醒','国庆黄金周房源紧张，请提前预订并留意订单状态。',1,1,'2026-10-07 13:59:22'),(3,'实名认证须知','为保障交易安全，请用户与商家尽快完成实名认证。',1,1,'2026-10-07 13:59:22'),(4,'系统维护通知','平台将于每周日凌晨进行例行维护，期间暂停服务，敬请谅解。',1,0,'2026-10-07 13:59:22');

/*Table structure for table `biz_order` */

DROP TABLE IF EXISTS `biz_order`;

CREATE TABLE `biz_order` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '涓婚敭ID',
  `order_no` varchar(32) NOT NULL COMMENT '璁㈠崟鍙?鍞?竴)',
  `user_id` bigint(20) NOT NULL COMMENT '涓嬪崟鐢ㄦ埛ID',
  `order_type` tinyint(4) NOT NULL COMMENT '璁㈠崟绫诲瀷:1閰掑簵 2鏅?偣',
  `target_id` bigint(20) NOT NULL COMMENT '鐩?爣閰掑簵/鏅?偣ID',
  `target_name` varchar(100) DEFAULT NULL COMMENT '鐩?爣鍚嶇О蹇?収',
  `total_amount` decimal(10,2) NOT NULL COMMENT '璁㈠崟鎬婚噾棰',
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '鐘舵?:0寰呮敮浠?1宸叉敮浠?2宸插彇娑?3宸插畬鎴?4宸查?娆',
  `contact_name` varchar(50) DEFAULT NULL COMMENT '鑱旂郴浜哄?鍚',
  `contact_phone` varchar(20) DEFAULT NULL COMMENT '鑱旂郴鐢佃瘽',
  `remark` varchar(500) DEFAULT NULL COMMENT '澶囨敞',
  `pay_time` datetime DEFAULT NULL COMMENT '鏀?粯鏃堕棿',
  `cancel_time` datetime DEFAULT NULL COMMENT '鍙栨秷鏃堕棿',
  `finish_time` datetime DEFAULT NULL COMMENT '瀹屾垚鏃堕棿',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_user` (`user_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=80 DEFAULT CHARSET=utf8mb4 COMMENT='璁㈠崟琛';

