/*Table structure for table `biz_order_item` */

DROP TABLE IF EXISTS `biz_order_item`;

CREATE TABLE `biz_order_item` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '涓婚敭ID',
  `order_id` bigint(20) NOT NULL COMMENT '鎵?睘璁㈠崟ID',
  `item_type` tinyint(4) NOT NULL COMMENT '鏄庣粏绫诲瀷:1鎴垮瀷 2绁ㄥ瀷',
  `item_id` bigint(20) NOT NULL COMMENT '鎴垮瀷/绁ㄥ瀷ID',
  `item_name` varchar(100) DEFAULT NULL COMMENT '鍚嶇О蹇?収',
  `price` decimal(10,2) NOT NULL COMMENT '鍗曚环',
  `quantity` int(11) NOT NULL DEFAULT '1' COMMENT '鏁伴噺(鎴块棿鏁?绁ㄦ暟)',
  `subtotal` decimal(10,2) NOT NULL COMMENT '灏忚?',
  `check_in_date` date DEFAULT NULL COMMENT '鍏ヤ綇鏃ユ湡(閰掑簵)',
  `check_out_date` date DEFAULT NULL COMMENT '绂诲簵鏃ユ湡(閰掑簵)',
  `visit_date` date DEFAULT NULL COMMENT '娓哥帺鏃ユ湡(鏅?偣)',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  PRIMARY KEY (`id`),
  KEY `idx_order` (`order_id`),
  KEY `idx_item` (`item_type`,`item_id`)
) ENGINE=InnoDB AUTO_INCREMENT=80 DEFAULT CHARSET=utf8mb4 COMMENT='璁㈠崟鏄庣粏琛';

