/*Table structure for table `biz_scenic_spot` */

DROP TABLE IF EXISTS `biz_scenic_spot`;

CREATE TABLE `biz_scenic_spot` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '涓婚敭ID',
  `merchant_id` bigint(20) DEFAULT NULL COMMENT '鎵?睘鍟嗗?ID(鍙?┖,骞冲彴缁熶竴绠＄悊)',
  `name` varchar(100) NOT NULL COMMENT '鏅?偣鍚嶇О',
  `category_id` bigint(20) DEFAULT NULL COMMENT '鍒嗙被ID',
  `province` varchar(50) DEFAULT NULL COMMENT '鐪',
  `city` varchar(50) DEFAULT NULL COMMENT '甯',
  `address` varchar(255) DEFAULT NULL COMMENT '璇︾粏鍦板潃',
  `open_time` varchar(100) DEFAULT NULL COMMENT '寮?斁鏃堕棿',
  `cover_image` varchar(255) DEFAULT NULL COMMENT '灏侀潰鍥綰RL',
  `images` text COMMENT '鍥剧墖闆?閫楀彿鍒嗛殧)',
  `description` text COMMENT '鏅?偣浠嬬粛',
  `rating` decimal(2,1) NOT NULL DEFAULT '5.0' COMMENT '缁煎悎璇勫垎',
  `comment_count` int(11) NOT NULL DEFAULT '0' COMMENT '璇勪环鏁',
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '鐘舵?:0寰呭?鏍?1涓婃灦 2椹冲洖 3涓嬫灦',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  PRIMARY KEY (`id`),
  KEY `idx_merchant` (`merchant_id`),
  KEY `idx_category` (`category_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COMMENT='鏅?偣琛';

