insert  into `biz_scenic_spot`(`id`,`merchant_id`,`name`,`category_id`,`province`,`city`,`address`,`open_time`,`cover_image`,`images`,`description`,`rating`,`comment_count`,`status`,`create_time`,`update_time`) values (1,NULL,'中山陵',7,'江苏','南京','玄武区石象路7号','08:30-17:00','/upload/jiangsu-spot-1.png',NULL,'中国近代伟大的民主革命先行者孙中山先生的陵寝，庄严肃穆。','4.9',580,1,'2026-10-07 13:59:22','2026-10-28 13:32:57'),(2,NULL,'夫子庙·秦淮风光带',7,'江苏','南京','秦淮区夫子庙','08:00-22:00','/upload/jiangsu-spot-2.png',NULL,'十里秦淮，桨声灯影，六朝金粉之地。','4.7',720,1,'2026-10-07 13:59:22','2026-10-28 13:32:57'),(3,NULL,'南京博物院',10,'江苏','南京','玄武区中山东路321号','09:00-17:00','/upload/jiangsu-spot-3.png',NULL,'中国三大博物馆之一，馆藏丰富。','4.8',310,1,'2026-10-07 13:59:22','2026-10-28 13:32:57'),(4,NULL,'玄武湖公园',6,'江苏','南京','玄武区玄武门','06:00-22:00','/upload/jiangsu-spot-4.png',NULL,'六朝古都最大的城中湖，湖光山色。','4.7',460,1,'2026-10-07 13:59:22','2026-10-28 13:32:57'),(5,21,'拙政园',9,'江苏','苏州','姑苏区东北街178号','07:30-17:30','/upload/jiangsu-spot-5.png',NULL,'中国四大名园之一，苏州园林典范。','4.9',690,1,'2026-10-07 13:59:22','2026-10-28 13:32:57'),(6,21,'周庄古镇',9,'江苏','苏州','昆山市周庄镇','08:00-21:00','/upload/jiangsu-spot-6.png',NULL,'中国第一水乡，小桥流水人家。','4.7',540,1,'2026-10-07 13:59:22','2026-10-28 13:32:57'),(7,21,'太湖鼋头渚',6,'江苏','无锡','滨湖区鼋渚路1号','08:00-17:30','/upload/jiangsu-spot-7.png',NULL,'太湖佳绝处，樱花谷闻名。','4.8',380,1,'2026-10-07 13:59:22','2026-10-28 13:32:57'),(8,21,'灵山胜境',7,'江苏','无锡','滨湖区马山','08:00-17:00','/upload/jiangsu-spot-8.png',NULL,'灵山大佛，佛教文化圣地。','4.8',290,1,'2026-10-07 13:59:22','2026-10-28 13:32:57'),(9,21,'瘦西湖',6,'江苏','扬州','邗江区大虹桥路28号','07:00-17:30','/upload/jiangsu-spot-9.png',NULL,'园林之盛，甲于天下。','4.9',620,1,'2026-10-07 13:59:22','2026-10-28 13:32:57'),(10,21,'中华恐龙园',8,'江苏','常州','新北区河海东路60号','09:00-17:00','/upload/jiangsu-spot-10.png',NULL,'恐龙主题乐园，亲子游乐天堂。','4.7',850,1,'2026-10-07 13:59:22','2026-10-28 13:32:57'),(11,NULL,'花果山',6,'江苏','连云港','海州区花果山','08:00-17:30','/upload/jiangsu-spot-11.png',NULL,'西游记孙悟空的老家，云台胜境。','4.6',260,1,'2026-10-07 13:59:22','2026-10-28 13:32:57'),(12,NULL,'