/*Table structure for table `biz_spot_ticket` */

DROP TABLE IF EXISTS `biz_spot_ticket`;

CREATE TABLE `biz_spot_ticket` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '涓婚敭ID',
  `spot_id` bigint(20) NOT NULL COMMENT '鎵?睘鏅?偣ID',
  `name` varchar(100) NOT NULL COMMENT '绁ㄥ瀷鍚嶇О(鎴愪汉绁?瀛︾敓绁ㄧ瓑)',
  `price` decimal(10,2) NOT NULL COMMENT '绁ㄤ环(鍏?',
  `stock` int(11) NOT NULL DEFAULT '0' COMMENT '搴撳瓨',
  `sales` int(11) NOT NULL DEFAULT '0' COMMENT '閿?噺',
  `valid_days` int(11) DEFAULT NULL COMMENT '鏈夋晥鏈?澶?',
  `description` varchar(500) DEFAULT NULL COMMENT '绁ㄥ瀷鎻忚堪',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '鐘舵?:0涓嬫灦 1涓婃灦',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  PRIMARY KEY (`id`),
  KEY `idx_spot` (`spot_id`)
) ENGINE=InnoDB AUTO_INCREMENT=73 DEFAULT CHARSET=utf8mb4 COMMENT='鏅?偣绁ㄥ瀷琛';

