/*Table structure for table `sys_user` */

DROP TABLE IF EXISTS `sys_user`;

CREATE TABLE `sys_user` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '涓婚敭ID',
  `username` varchar(50) NOT NULL COMMENT '鐢ㄦ埛鍚',
  `password` varchar(100) NOT NULL COMMENT '瀵嗙爜(BCrypt鍔犲瘑)',
  `nickname` varchar(50) DEFAULT NULL COMMENT '鏄电О',
  `phone` varchar(20) DEFAULT NULL COMMENT '鎵嬫満鍙',
  `email` varchar(100) DEFAULT NULL COMMENT '閭??',
  `avatar` varchar(255) DEFAULT NULL COMMENT '澶村儚URL',
  `gender` tinyint(4) NOT NULL DEFAULT '0' COMMENT '鎬у埆:0鏈?煡 1鐢?2濂',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '鐘舵?:0绂佺敤 1姝ｅ父',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  `deleted` tinyint(4) NOT NULL DEFAULT '0' COMMENT '閫昏緫鍒犻櫎:0鏈?垹 1宸插垹',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username` (`username`),
  KEY `idx_phone` (`phone`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COMMENT='鐢ㄦ埛琛';

